import React, { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence, useMotionValue, useSpring } from "framer-motion";
import './App.css';

// СҰРАҚТАР БАЗАСЫ (Ештеңе қысқартылмады)
const QUESTIONS_DATABASE = {
  1: [
    { q: "«Ескендір» поэмасының авторы кім?", a: ["Абай", "Шәкәрім", "Мағжан", "Мұхтар"], c: 0 },
    { q: "Ескендірдің ұстазы кім?", a: ["Сократ", "Платон", "Аристотель", "Әл-Фараби"], c: 2 },
    { q: "Ескендір қай елдің патшасы?", a: ["Рим", "Македония", "Парсы", "Египет"], c: 1 },
    { q: "Поэмадағы басты кейіпкердің бірі?", a: ["Ахиллес", "Ескендір", "Гектор", "Цезарь"], c: 1 },
    { q: "Абай бұл поэманы қай жылы жазды?", a: ["1880", "1900", "1895", "1890"], c: 2 }
  ]
};

function App() {
  // Ойынның күйлері
  const [gameState, setGameState] = useState('start'); // 'start' немесе 'map'
  const [unlockedLevel, setUnlockedLevel] = useState(1);
  const [activeLvl, setActiveLvl] = useState(null);
  const [currentQIndex, setCurrentQIndex] = useState(0);
  const [selectedAns, setSelectedAns] = useState(null);
  const [feedback, setFeedback] = useState(null);

  const mapAreaRef = useRef(null);
  const containerRef = useRef(null);

  // Картаның қозғалысы (Scroll + Drag)
  const mapY = useMotionValue(0);
  const smoothY = useSpring(mapY, { damping: 30, stiffness: 150 });

  // Сенің нүктелерің
  const [points, setPoints] = useState([
    { "id": 1, "x": 62.10, "y": 43.40, "s": 0.9 },
    { "id": 2, "x": 45.26, "y": 68.03, "s": 1 },
    { "id": 3, "x": 43.42, "y": 47.33, "s": 0.85 },
    { "id": 4, "x": 66.84, "y": 40.87, "s": 0.85 },
    { "id": 5, "x": 51.84, "y": 62.64, "s": 0.9 },
    { "id": 6, "x": 52.36, "y": 34.41, "s": 0.85 },
    { "id": 7, "x": 59.21, "y": 28.03, "s": 0.85 },
    { "id": 8, "x": 54.73, "y": 23.66, "s": 0.85 },
    { "id": 9, "x": 51.57, "y": 15.45, "s": 0.6 },
    { "id": 10, "x": 49.21, "y": 8.47, "s": 0.8, "type": "finish_label" }
  ]);

  // КОЛЕСОМЕН АЙНАЛДЫРУ
  useEffect(() => {
    const handleWheel = (e) => {
      if (activeLvl || gameState === 'start') return;
      e.preventDefault();
      const move = mapY.get() - e.deltaY;
      const limit = -(1832 - window.innerHeight);
      if (move <= 0 && move >= limit) mapY.set(move);
    };

    const area = containerRef.current;
    if (area) {
      area.addEventListener('wheel', handleWheel, { passive: false });
    }
    return () => {
      if (area) area.removeEventListener('wheel', handleWheel);
    };
  }, [activeLvl, gameState, mapY]);

  // ТИЫНДАРДЫ ЖЫЛЖЫТУ (КОНСОЛЬГЕ ШЫҒАРУ)
  const handleDragEnd = (id, info) => {
    const rect = mapAreaRef.current.getBoundingClientRect();
    const nx = ((info.point.x - rect.left) / rect.width) * 100;
    const ny = ((info.point.y - rect.top) / rect.height) * 100;

    const up = points.map(p => p.id === id ? { ...p, x: Number(nx.toFixed(2)), y: Number(ny.toFixed(2)) } : p);
    setPoints(up);
    console.log("ЖАҢА КОРДИНАТАЛАР:", JSON.stringify(up, null, 2));
  };

  // ЖАУАПТЫ ТЕКСЕРУ
  const checkAnswer = (idx) => {
    if (feedback) return;
    setSelectedAns(idx);
    const correct = QUESTIONS_DATABASE[1][currentQIndex].c;
    setFeedback(idx === correct ? 'correct' : 'wrong');
  };

  // КЕЛЕСІ СҰРАҚ НЕМЕСЕ ҚАЙТАЛАУ
  const handleAction = () => {
    const questions = QUESTIONS_DATABASE[1];
    if (feedback === 'correct') {
      if (currentQIndex < questions.length - 1) {
        setCurrentQIndex(c => c + 1);
        setFeedback(null); setSelectedAns(null);
      } else {
        setUnlockedLevel(prev => Math.max(prev, activeLvl + 1));
        setActiveLvl(null); setCurrentQIndex(0); setFeedback(null); setSelectedAns(null);
      }
    } else {
      setFeedback(null); setSelectedAns(null);
    }
  };

  return (
    <div className="game-wrapper" ref={containerRef}>
      <AnimatePresence>
        {gameState === 'start' && (
          <motion.div className="start-screen" exit={{ opacity: 0, scale: 1.1 }}>
            <h1 className="main-title">ЕСКЕНДІР</h1>
            <p className="subtitle">Абай Құнанбаев</p>
            <button className="start-btn" onClick={() => setGameState('map')}>ОЙНАУ</button>
          </motion.div>
        )}

        {gameState === 'map' && (
          <motion.div className="map-container" initial={{ opacity: 0 }}>
            <div className="ui-header">
              <button className="back-btn" onClick={() => setGameState('start')}>АРТҚА</button>
              <div className="score">Level: {unlockedLevel}</div>
            </div>

            <motion.div className="map-scroll-area" style={{ y: smoothY }} drag="y" dragConstraints={{ top: -(1832 - window.innerHeight), bottom: 0 }}>
              <div ref={mapAreaRef} className="map-content">
                <img src={process.env.PUBLIC_URL + "/img.jpg"} alt="Map" className="map-img" draggable="false" />
                {points.map((p) => {
                    const isLocked = p.id > unlockedLevel;
                    return (
                      <motion.div key={p.id} className="node" drag dragMomentum={false} onDragEnd={(e, info) => handleDragEnd(p.id, info)} style={{ left: `${p.x}%`, top: `${p.y}%`, position: 'absolute' }}>
                        <div className="coin-perspective" style={{ transform: `scale(${p.s})` }} onClick={() => !isLocked && setActiveLvl(p.id)}>
                          <div className={`coin ${isLocked ? 'silver' : 'gold'}`}>
                            {p.type === 'finish_label' ? '🏁' : p.id}
                          </div>
                        </div>
                      </motion.div>
                    )
                })}
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {activeLvl && (
          <div className="quiz-overlay">
            <motion.div className="quiz-card" initial={{ y: 100, opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={{ y: 100, opacity: 0 }}>
              <div className="quiz-top">
                <div className="progress-container">
                    <motion.div className="progress-bar" animate={{ width: `${((currentQIndex+1)/5)*100}%` }} />
                </div>
                <button className="close-x" onClick={() => setActiveLvl(null)}>✕</button>
              </div>

              <h2 className="question-text">{QUESTIONS_DATABASE[1][currentQIndex].q}</h2>

              <div className="options-grid">
                {QUESTIONS_DATABASE[1][currentQIndex].a.map((ans, i) => (
                  <button
                    key={i}
                    disabled={feedback}
                    className={`opt-btn ${selectedAns === i ? feedback : ''} ${feedback && QUESTIONS_DATABASE[1][currentQIndex].c === i ? 'correct' : ''}`}
                    onClick={() => checkAnswer(i)}
                  >
                    {ans}
                  </button>
                ))}
              </div>

              {feedback && (
                <motion.div className="feedback-area" initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }}>
                   <div className={`status-msg ${feedback}`}>
                      {feedback === 'correct' ? "Керемет! Дұрыс жауап." : "Бұл жолы қате болды..."}
                   </div>
                   <button className={`action-btn ${feedback}`} onClick={handleAction}>
                      {feedback === 'correct' ? "КЕЛЕСІ" : "ҚАЙТА КӨРУ"}
                   </button>
                </motion.div>
              )}
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
}

export default App;